import React, { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";
import { API_BASE } from "../config";

const MIN_DATE = new Date("2020-01-01");
const isValidDate = (d) => {
  const date = new Date(d);
  return d && !isNaN(date.getTime()) && date >= MIN_DATE;
};
const daysBetween = (a, b) =>
  Math.round(Math.abs(new Date(b) - new Date(a)) / (1000 * 60 * 60 * 24));
const fmt = (n) => `$${Math.abs(Number(n)).toFixed(2)}`;
const fmtSigned = (n) => `${Number(n) >= 0 ? "+" : "-"}${fmt(n)}`;

const isBinder = (name) => {
  if (!name) return false;
  const n = name.toLowerCase();
  return n.includes("bin") || n.includes("bnder") || n.includes("biner");
};

// Detect which game a card belongs to based on set name
const detectGame = (item) => {
  const set = (item.set || "").toLowerCase();
  const name = (item.name || "").toLowerCase();

  // Riftbound keywords
  const riftboundSets = [
    "origins",
    "spiritforged",
    "unleashed",
    "ogn",
    "sfd",
    "unl",
  ];
  if (riftboundSets.some((k) => set.includes(k))) return "Riftbound";

  // One Piece
  if (set.includes("op") || name.includes("one piece")) return "One Piece";

  // Everything else = Pokemon
  return "Pokémon";
};

const GAME_COLORS = {
  Pokémon: "#ffcb05",
  Riftbound: "#4ab3d8",
  "One Piece": "#e05c5c",
};

const WINDOWS = [
  { label: "Last 1 Month", months: 1 },
  { label: "Last 3 Months", months: 3 },
  { label: "Last 6 Months", months: 6 },
  { label: "Last 12 Months", months: 12 },
  { label: "All Time", months: null },
];

const StatRow = ({ label, value, color, sub }) => (
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      padding: "12px 0",
      borderBottom: "1px solid var(--border)",
    }}
  >
    <div>
      <div style={{ fontSize: 14, color: "var(--text)" }}>{label}</div>
      {sub && (
        <div style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 2 }}>
          {sub}
        </div>
      )}
    </div>
    <div
      style={{
        fontFamily: "'Bebas Neue', sans-serif",
        fontSize: 22,
        letterSpacing: 1,
        color: color || "var(--text)",
      }}
    >
      {value}
    </div>
  </div>
);

const SectionTitle = ({ children }) => (
  <h2
    style={{
      fontFamily: "'Bebas Neue', sans-serif",
      fontSize: 20,
      letterSpacing: 2,
      color: "var(--text-muted)",
      marginBottom: 16,
      marginTop: 32,
    }}
  >
    {children}
  </h2>
);

const InsightBox = ({ emoji, title, body, color }) => (
  <div
    className="card"
    style={{ borderLeft: `3px solid ${color || "var(--blue)"}` }}
  >
    <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
      <span style={{ fontSize: 20 }}>{emoji}</span>
      <div>
        <div style={{ fontWeight: 600, fontSize: 14, marginBottom: 4 }}>
          {title}
        </div>
        <div
          style={{ fontSize: 13, color: "var(--text-muted)", lineHeight: 1.5 }}
        >
          {body}
        </div>
      </div>
    </div>
  </div>
);

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
          borderRadius: "var(--radius-sm)",
          padding: "10px 14px",
          fontSize: 13,
        }}
      >
        <div style={{ color: "var(--text-muted)", marginBottom: 6 }}>
          {label}
        </div>
        {payload.map((p) => (
          <div
            key={p.dataKey}
            style={{
              color: p.value >= 0 ? "var(--green)" : "var(--danger)",
              fontWeight: 700,
            }}
          >
            {fmtSigned(p.value)}
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const MatchedEntries = ({ binderExpenses, binderOther }) => {
  const [open, setOpen] = useState(false);
  const total = binderExpenses.length + binderOther.length;
  return (
    <div style={{ marginTop: 16 }}>
      <button
        className="btn btn-secondary btn-sm"
        onClick={() => setOpen((p) => !p)}
        style={{ width: "100%", justifyContent: "space-between" }}
      >
        <span>Matched Entries ({total})</span>
        <span>{open ? "▲" : "▼"}</span>
      </button>
      {open && (
        <div
          style={{
            marginTop: 8,
            padding: 12,
            background: "var(--bg)",
            borderRadius: "var(--radius-sm)",
          }}
        >
          {binderExpenses.length > 0 && (
            <div style={{ marginBottom: 8 }}>
              <div
                style={{
                  fontSize: 12,
                  color: "var(--danger)",
                  marginBottom: 4,
                  fontWeight: 700,
                }}
              >
                Expenses
              </div>
              {binderExpenses.map((e) => (
                <div
                  key={e._id}
                  style={{
                    fontSize: 12,
                    color: "var(--text-muted)",
                    display: "flex",
                    justifyContent: "space-between",
                    padding: "2px 0",
                  }}
                >
                  <span>{e.name}</span>
                  <span>-{fmt(e.amount)}</span>
                </div>
              ))}
            </div>
          )}
          {binderOther.length > 0 && (
            <div>
              <div
                style={{
                  fontSize: 12,
                  color: "var(--green)",
                  marginBottom: 4,
                  fontWeight: 700,
                }}
              >
                Sales
              </div>
              {binderOther.map((o) => (
                <div
                  key={o._id}
                  style={{
                    fontSize: 12,
                    color: "var(--text-muted)",
                    display: "flex",
                    justifyContent: "space-between",
                    padding: "2px 0",
                  }}
                >
                  <span>{o.name}</span>
                  <span>+{fmt(o.amount)}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const GameCard = ({ game, data }) => {
  const color = GAME_COLORS[game] || "var(--text)";
  const winRate =
    data.sold > 0 ? ((data.wins / data.sold) * 100).toFixed(0) : 0;
  const avgProfit = data.sold > 0 ? data.profit / data.sold : 0;
  const avgHold =
    data.holdDays.length > 0
      ? Math.round(
          data.holdDays.reduce((s, d) => s + d, 0) / data.holdDays.length,
        )
      : null;

  return (
    <div className="card" style={{ borderTop: `3px solid ${color}` }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 16,
        }}
      >
        <div
          style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: 22,
            letterSpacing: 1,
            color,
          }}
        >
          {game}
        </div>
        <div style={{ textAlign: "right" }}>
          <div
            style={{
              fontSize: 11,
              color: "var(--text-muted)",
              textTransform: "uppercase",
              letterSpacing: "0.8px",
            }}
          >
            Total Profit
          </div>
          <div
            style={{
              fontFamily: "'Bebas Neue', sans-serif",
              fontSize: 24,
              color: data.profit >= 0 ? "var(--green)" : "var(--danger)",
            }}
          >
            {fmtSigned(data.profit)}
          </div>
        </div>
      </div>
      <StatRow
        label="Cards Sold"
        value={data.sold}
        sub={`${data.unsold} still in inventory`}
      />
      <StatRow
        label="Total Revenue"
        value={fmt(data.revenue)}
        color="var(--green)"
      />
      <StatRow
        label="Avg Profit / Card"
        value={fmtSigned(avgProfit)}
        color={avgProfit >= 0 ? "var(--green)" : "var(--danger)"}
      />
      <StatRow
        label="Win Rate"
        value={`${winRate}%`}
        color={Number(winRate) >= 60 ? "var(--green)" : "var(--danger)"}
        sub={`${data.wins} of ${data.sold} profitable`}
      />
      {avgHold !== null && (
        <StatRow
          label="Avg Hold Time"
          value={`${avgHold} days`}
          color="var(--blue)"
        />
      )}
      <StatRow
        label="Inventory Value"
        value={fmt(data.inventoryValue)}
        sub="Unsold at cost"
      />
    </div>
  );
};

const Insights = () => {
  const [windowIdx, setWindowIdx] = useState(1);
  const [allItems, setAllItems] = useState([]);
  const [allExpenses, setAllExpenses] = useState([]);
  const [allOther, setAllOther] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [ir, er, or] = await Promise.all([
          fetch(`${API_BASE}/api/items`),
          fetch(`${API_BASE}/api/expenses`),
          fetch(`${API_BASE}/api/other`),
        ]);
        const [items, expenses, other] = await Promise.all([
          ir.json(),
          er.json(),
          or.json(),
        ]);
        setAllItems(items);
        setAllExpenses(expenses);
        setAllOther(other);
      } catch {
        setError(true);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const win = WINDOWS[windowIdx];
  const cutoff = win.months
    ? new Date(Date.now() - win.months * 30.44 * 24 * 60 * 60 * 1000)
    : MIN_DATE;
  const inWindow = (d) => isValidDate(d) && new Date(d) >= cutoff;

  const soldInWindow = allItems.filter(
    (i) => i.soldPrice != null && inWindow(i.soldDate),
  );
  const boughtInWindow = allItems.filter((i) => inWindow(i.purchaseDate));
  const expensesInWindow = allExpenses.filter((e) => inWindow(e.date));
  const otherInWindow = allOther.filter((o) => inWindow(o.date));

  const binderExpenses = expensesInWindow.filter((e) => isBinder(e.name));
  const binderOther = otherInWindow.filter((o) => isBinder(o.name));
  const nonBinderExpenses = expensesInWindow.filter((e) => !isBinder(e.name));
  const nonBinderOther = otherInWindow.filter((o) => !isBinder(o.name));

  const binderCost = binderExpenses.reduce((s, e) => s + Number(e.amount), 0);
  const binderRevenue = binderOther.reduce((s, o) => s + Number(o.amount), 0);
  const binderProfit = binderRevenue - binderCost;

  const binderByMonth = {};
  binderExpenses.forEach((e) => {
    if (!isValidDate(e.date)) return;
    const key = new Date(e.date).toISOString().slice(0, 7);
    if (!binderByMonth[key]) binderByMonth[key] = { cost: 0, revenue: 0 };
    binderByMonth[key].cost += Number(e.amount);
  });
  binderOther.forEach((o) => {
    if (!isValidDate(o.date)) return;
    const key = new Date(o.date).toISOString().slice(0, 7);
    if (!binderByMonth[key]) binderByMonth[key] = { cost: 0, revenue: 0 };
    binderByMonth[key].revenue += Number(o.amount);
  });
  const binderMonthlyData = Object.entries(binderByMonth)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, d]) => ({
      month: new Date(month + "-01").toLocaleString("default", {
        month: "short",
        year: "2-digit",
      }),
      profit: parseFloat((d.revenue - d.cost).toFixed(2)),
    }));

  const totalSold = soldInWindow.length;
  const totalBought = boughtInWindow.length;
  const totalRevenue = soldInWindow.reduce(
    (s, i) => s + Number(i.soldPrice),
    0,
  );
  const totalCOGS = soldInWindow.reduce(
    (s, i) => s + Number(i.purchasePrice),
    0,
  );
  const totalCardProfit = totalRevenue - totalCOGS;
  const totalExpenseAmt = nonBinderExpenses.reduce(
    (s, e) => s + Number(e.amount),
    0,
  );
  const totalOtherAmt = nonBinderOther.reduce(
    (s, o) => s + Number(o.amount),
    0,
  );
  const netProfit =
    totalCardProfit + totalOtherAmt - totalExpenseAmt + binderProfit;

  const avgProfitPerCard = totalSold > 0 ? totalCardProfit / totalSold : 0;
  const avgSalePrice = totalSold > 0 ? totalRevenue / totalSold : 0;

  const withHoldTime = soldInWindow
    .filter((i) => isValidDate(i.purchaseDate) && isValidDate(i.soldDate))
    .map((i) => ({ ...i, holdDays: daysBetween(i.purchaseDate, i.soldDate) }));
  const avgHoldDays =
    withHoldTime.length > 0
      ? Math.round(
          withHoldTime.reduce((s, i) => s + i.holdDays, 0) /
            withHoldTime.length,
        )
      : null;

  const wins = soldInWindow.filter(
    (i) => Number(i.soldPrice) > Number(i.purchasePrice),
  ).length;
  const winRate = totalSold > 0 ? ((wins / totalSold) * 100).toFixed(0) : 0;

  const monthCount =
    win.months ||
    Math.max(
      1,
      Math.round(
        (Date.now() - MIN_DATE.getTime()) / (30.44 * 24 * 60 * 60 * 1000),
      ),
    );
  const cardsPerMonth = (totalSold / monthCount).toFixed(1);
  const profitPerMonth = (netProfit / monthCount).toFixed(2);

  const byType = {};
  soldInWindow.forEach((i) => {
    if (!byType[i.itemType])
      byType[i.itemType] = { count: 0, profit: 0, revenue: 0 };
    byType[i.itemType].count++;
    byType[i.itemType].profit += Number(i.soldPrice) - Number(i.purchasePrice);
    byType[i.itemType].revenue += Number(i.soldPrice);
  });
  const typeData = Object.entries(byType).map(([type, d]) => ({
    type,
    profit: parseFloat(d.profit.toFixed(2)),
    avgProfit: parseFloat((d.profit / d.count).toFixed(2)),
    count: d.count,
  }));

  const monthlyMap = {};
  soldInWindow.forEach((i) => {
    if (!isValidDate(i.soldDate)) return;
    const key = new Date(i.soldDate).toISOString().slice(0, 7);
    if (!monthlyMap[key]) monthlyMap[key] = { profit: 0 };
    monthlyMap[key].profit += Number(i.soldPrice) - Number(i.purchasePrice);
  });
  nonBinderOther.forEach((o) => {
    if (!isValidDate(o.date)) return;
    const key = new Date(o.date).toISOString().slice(0, 7);
    if (!monthlyMap[key]) monthlyMap[key] = { profit: 0 };
    monthlyMap[key].profit += Number(o.amount);
  });
  nonBinderExpenses.forEach((e) => {
    if (!isValidDate(e.date)) return;
    const key = new Date(e.date).toISOString().slice(0, 7);
    if (!monthlyMap[key]) monthlyMap[key] = { profit: 0 };
    monthlyMap[key].profit -= Number(e.amount);
  });
  Object.entries(binderByMonth).forEach(([key, d]) => {
    if (!monthlyMap[key]) monthlyMap[key] = { profit: 0 };
    monthlyMap[key].profit += d.revenue - d.cost;
  });
  const monthlyData = Object.entries(monthlyMap)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, d]) => ({
      month: new Date(month + "-01").toLocaleString("default", {
        month: "short",
        year: "2-digit",
      }),
      profit: parseFloat(d.profit.toFixed(2)),
    }));

  const last3Cutoff = new Date(Date.now() - 3 * 30.44 * 24 * 60 * 60 * 1000);
  const recentSold = allItems.filter(
    (i) =>
      i.soldPrice != null &&
      isValidDate(i.soldDate) &&
      new Date(i.soldDate) >= last3Cutoff,
  );
  const recentCardsPerMonth = recentSold.length / 3;
  const recentAvgProfit =
    recentSold.length > 0
      ? recentSold.reduce(
          (s, i) => s + Number(i.soldPrice) - Number(i.purchasePrice),
          0,
        ) / recentSold.length
      : 0;
  const projectedProfitNextMonth = recentCardsPerMonth * recentAvgProfit;
  const recentAvgSalePrice =
    recentSold.length > 0
      ? recentSold.reduce((s, i) => s + Number(i.soldPrice), 0) /
        recentSold.length
      : 0;

  const unsoldItems = allItems.filter((i) => i.soldPrice == null);
  const inventoryValue = unsoldItems.reduce(
    (s, i) => s + Number(i.purchasePrice),
    0,
  );
  const sellThroughRate =
    allItems.length > 0
      ? (
          (allItems.filter((i) => i.soldPrice != null).length /
            allItems.length) *
          100
        ).toFixed(0)
      : 0;

  // ── Game breakdown ──
  const games = ["Pokémon", "Riftbound", "One Piece"];
  const gameStats = {};
  games.forEach((g) => {
    gameStats[g] = {
      sold: 0,
      unsold: 0,
      profit: 0,
      revenue: 0,
      wins: 0,
      holdDays: [],
      inventoryValue: 0,
    };
  });

  // Use all items for game breakdown (not window filtered) so unsold counts are accurate
  // But sold stats use window
  allItems.forEach((item) => {
    const game = detectGame(item);
    if (!gameStats[game]) return;
    if (item.soldPrice == null) {
      gameStats[game].unsold++;
      gameStats[game].inventoryValue += Number(item.purchasePrice);
    }
  });

  soldInWindow.forEach((item) => {
    const game = detectGame(item);
    if (!gameStats[game]) return;
    const profit = Number(item.soldPrice) - Number(item.purchasePrice);
    gameStats[game].sold++;
    gameStats[game].profit += profit;
    gameStats[game].revenue += Number(item.soldPrice);
    if (profit > 0) gameStats[game].wins++;
    if (isValidDate(item.purchaseDate) && isValidDate(item.soldDate)) {
      gameStats[game].holdDays.push(
        daysBetween(item.purchaseDate, item.soldDate),
      );
    }
  });

  // Only show games that have data
  const activeGames = games.filter(
    (g) => gameStats[g].sold > 0 || gameStats[g].unsold > 0,
  );

  // Game comparison chart data
  const gameChartData = activeGames.map((g) => ({
    game: g,
    profit: parseFloat(gameStats[g].profit.toFixed(2)),
  }));

  // Best performing game
  const bestGame =
    activeGames.length > 1
      ? activeGames.reduce(
          (best, g) =>
            gameStats[g].profit > gameStats[best].profit ? g : best,
          activeGames[0],
        )
      : null;

  // ── Insights ──
  const insights = [];
  if (avgHoldDays !== null) {
    if (avgHoldDays <= 14) {
      insights.push({
        emoji: "⚡",
        title: "Fast Inventory Turnover",
        color: "var(--green)",
        body: `Cards are selling in ${avgHoldDays} days on average. Your inventory is moving quickly — you could buy more aggressively and expect fast turnaround.`,
      });
    } else if (avgHoldDays <= 45) {
      insights.push({
        emoji: "📦",
        title: "Healthy Hold Time",
        color: "var(--blue)",
        body: `Average of ${avgHoldDays} days to sell is solid. You're not sitting on cards too long, but there's room to push pricing slightly.`,
      });
    } else {
      insights.push({
        emoji: "⏳",
        title: "Cards Are Sitting",
        color: "var(--accent)",
        body: `${avgHoldDays} days average hold time is on the longer side. Consider dropping prices on older inventory or focusing on more liquid card types.`,
      });
    }
  }
  if (Number(winRate) >= 80) {
    insights.push({
      emoji: "🎯",
      title: "Excellent Win Rate",
      color: "var(--green)",
      body: `${winRate}% of sales are profitable. You're buying well. The remaining losses are worth taking to keep inventory moving.`,
    });
  } else if (Number(winRate) < 60) {
    insights.push({
      emoji: "⚠️",
      title: "Win Rate Needs Attention",
      color: "var(--danger)",
      body: `Only ${winRate}% of sales are profitable. Consider tightening buy prices or focusing on card types with better margins.`,
    });
  }
  if (projectedProfitNextMonth > 0) {
    insights.push({
      emoji: "📈",
      title: "Growth Projection",
      color: "var(--green)",
      body: `Based on your last 3 months (${recentSold.length} cards sold, avg ${fmt(recentAvgProfit)} profit each), you're on track for roughly ${fmt(projectedProfitNextMonth)} profit next month if velocity holds.`,
    });
  } else if (projectedProfitNextMonth < 0) {
    insights.push({
      emoji: "📉",
      title: "Recent Trend is Negative",
      color: "var(--danger)",
      body: `Recent sales are averaging a loss of ${fmt(Math.abs(recentAvgProfit))} per card. Focus on selling older inventory or reassess pricing.`,
    });
  }
  if (inventoryValue > 0 && recentCardsPerMonth > 0) {
    const monthsToSell = (unsoldItems.length / recentCardsPerMonth).toFixed(1);
    insights.push({
      emoji: "🏪",
      title: "Inventory Runway",
      color: "var(--blue)",
      body: `At your current pace of ${recentCardsPerMonth.toFixed(1)} cards/month, it would take ~${monthsToSell} months to sell through ${unsoldItems.length} unsold items (${fmt(inventoryValue)} at cost).`,
    });
  }
  if (binderCost > 0 || binderRevenue > 0) {
    if (binderProfit > 0) {
      insights.push({
        emoji: "📒",
        title: "Binder is Profitable",
        color: "var(--green)",
        body: `The binder made ${fmt(binderProfit)} profit this period — ${fmt(binderRevenue)} in sales against ${fmt(binderCost)} in stocking costs.`,
      });
    } else if (binderProfit < 0) {
      insights.push({
        emoji: "📒",
        title: "Binder Running at a Loss",
        color: "var(--danger)",
        body: `The binder cost ${fmt(binderCost)} to stock but only generated ${fmt(binderRevenue)} in sales. Consider restocking less frequently or raising prices.`,
      });
    }
  }
  if (bestGame) {
    const g = gameStats[bestGame];
    const avgP = g.sold > 0 ? (g.profit / g.sold).toFixed(2) : 0;
    insights.push({
      emoji: "🎮",
      title: `${bestGame} is Your Best Game`,
      color: GAME_COLORS[bestGame] || "var(--accent)",
      body: `${bestGame} leads with ${fmtSigned(g.profit)} total profit this period — ${g.sold} cards sold at an average of ${fmtSigned(avgP)} each. Worth prioritizing when sourcing.`,
    });
  }
  if (typeData.length > 1) {
    const best = [...typeData].sort((a, b) => b.avgProfit - a.avgProfit)[0];
    insights.push({
      emoji: "💡",
      title: `${best.type}s Are Your Best Format`,
      color: "var(--accent)",
      body: `${best.type}s average ${fmtSigned(best.avgProfit)} profit per sale — higher than your other formats. Worth prioritizing when sourcing.`,
    });
  }

  if (loading)
    return (
      <div>
        <h1 className="page-title">Insights</h1>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
            gap: 16,
          }}
        >
          {Array(8)
            .fill(0)
            .map((_, i) => (
              <div key={i} className="card">
                <div
                  className="skeleton"
                  style={{ height: 12, width: "60%", marginBottom: 10 }}
                />
                <div
                  className="skeleton"
                  style={{ height: 28, width: "80%" }}
                />
              </div>
            ))}
        </div>
      </div>
    );

  if (error)
    return (
      <div>
        <h1 className="page-title">Insights</h1>
        <div className="card" style={{ color: "var(--danger)" }}>
          ⚠️ Could not load data.
        </div>
      </div>
    );

  return (
    <div>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 28,
          flexWrap: "wrap",
          gap: 12,
        }}
      >
        <h1 className="page-title" style={{ marginBottom: 0 }}>
          Insights
        </h1>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {WINDOWS.map((w, i) => (
            <button
              key={i}
              className={`btn btn-sm ${windowIdx === i ? "btn-primary" : "btn-secondary"}`}
              onClick={() => setWindowIdx(i)}
            >
              {w.label}
            </button>
          ))}
        </div>
      </div>

      {/* Key Metrics */}
      <SectionTitle>Key Metrics — {win.label}</SectionTitle>
      <div className="card" style={{ marginBottom: 8 }}>
        <StatRow
          label="Cards Sold"
          value={totalSold}
          sub={`${totalBought} bought in same period`}
        />
        <StatRow
          label="Net Profit"
          value={fmtSigned(netProfit)}
          color={netProfit >= 0 ? "var(--green)" : "var(--danger)"}
        />
        <StatRow
          label="Total Revenue"
          value={fmt(totalRevenue)}
          color="var(--green)"
          sub="Sold price of all items"
        />
        <StatRow
          label="Avg Profit / Card"
          value={fmtSigned(avgProfitPerCard)}
          color={avgProfitPerCard >= 0 ? "var(--green)" : "var(--danger)"}
        />
        <StatRow label="Avg Sale Price" value={fmt(avgSalePrice)} />
        <StatRow
          label="Win Rate"
          value={`${winRate}%`}
          color={Number(winRate) >= 60 ? "var(--green)" : "var(--danger)"}
          sub={`${wins} of ${totalSold} sales profitable`}
        />
        {avgHoldDays !== null && (
          <StatRow
            label="Avg Days to Sell"
            value={`${avgHoldDays} days`}
            color="var(--blue)"
            sub="From purchase to sale date"
          />
        )}
        <StatRow
          label="Cards / Month"
          value={cardsPerMonth}
          sub="Avg sold per month"
        />
        <StatRow
          label="Profit / Month"
          value={fmtSigned(profitPerMonth)}
          color={Number(profitPerMonth) >= 0 ? "var(--green)" : "var(--danger)"}
          sub="Avg net profit per month"
        />
        <StatRow
          label="Overall Sell-Through"
          value={`${sellThroughRate}%`}
          sub="All-time % of inventory sold"
        />
      </div>

      {/* Projection */}
      <SectionTitle>Next Month Projection</SectionTitle>
      <div className="card" style={{ marginBottom: 8 }}>
        <div
          style={{
            fontSize: 12,
            color: "var(--text-muted)",
            paddingBottom: 16,
            borderBottom: "1px solid var(--border)",
            marginBottom: 4,
          }}
        >
          Based on last 3 months — {recentSold.length} cards sold,{" "}
          {fmt(recentAvgProfit)} avg profit each
        </div>
        <StatRow
          label="Projected Cards to Sell"
          value={`~${Math.round(recentCardsPerMonth)}`}
          sub="Based on recent velocity"
        />
        <StatRow
          label="Projected Profit"
          value={fmtSigned(projectedProfitNextMonth)}
          color={
            projectedProfitNextMonth >= 0 ? "var(--green)" : "var(--danger)"
          }
          sub="If current pace continues"
        />
        <StatRow
          label="Projected Revenue"
          value={fmt(recentCardsPerMonth * recentAvgSalePrice)}
          sub="Estimated gross sales"
        />
        <div
          style={{
            marginTop: 16,
            padding: 12,
            background: "var(--bg)",
            borderRadius: "var(--radius-sm)",
            fontSize: 12,
            color: "var(--text-muted)",
          }}
        >
          ⚠️ Projections are estimates based on recent trends. Card show
          attendance, inventory levels, and market conditions can significantly
          affect actual results.
        </div>
      </div>

      {/* Monthly chart */}
      {monthlyData.length > 1 && (
        <>
          <SectionTitle>Monthly Profit</SectionTitle>
          <div className="card" style={{ marginBottom: 8 }}>
            <ResponsiveContainer width="100%" height={240}>
              <BarChart
                data={monthlyData}
                margin={{ top: 10, right: 10, left: 10, bottom: 0 }}
              >
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="var(--border)"
                  vertical={false}
                />
                <XAxis
                  dataKey="month"
                  tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                  tickLine={false}
                  axisLine={false}
                />
                <YAxis
                  tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                  tickLine={false}
                  axisLine={false}
                  tickFormatter={(v) => `$${v}`}
                  width={65}
                />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="profit" radius={[4, 4, 0, 0]}>
                  {monthlyData.map((entry, i) => (
                    <Cell
                      key={i}
                      fill={entry.profit >= 0 ? "#4caf7d" : "#e05c5c"}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </>
      )}

      {/* By type */}
      {typeData.length > 0 && (
        <>
          <SectionTitle>Performance by Format</SectionTitle>
          <div className="card" style={{ marginBottom: 8 }}>
            {typeData
              .sort((a, b) => b.profit - a.profit)
              .map((t) => (
                <StatRow
                  key={t.type}
                  label={`${t.type}s`}
                  value={fmtSigned(t.profit)}
                  color={t.profit >= 0 ? "var(--green)" : "var(--danger)"}
                  sub={`${t.count} sold · avg ${fmtSigned(t.avgProfit)} each`}
                />
              ))}
          </div>
        </>
      )}

      {/* Game Performance */}
      {activeGames.length > 0 && (
        <>
          <SectionTitle>🎮 Performance by Game</SectionTitle>

          {/* Quick comparison bar chart */}
          {gameChartData.filter((g) => g.profit !== 0).length > 0 && (
            <div className="card" style={{ marginBottom: 16 }}>
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 600,
                  marginBottom: 12,
                  color: "var(--text-muted)",
                }}
              >
                Profit Comparison
              </div>
              <ResponsiveContainer width="100%" height={180}>
                <BarChart
                  data={gameChartData}
                  margin={{ top: 5, right: 10, left: 10, bottom: 0 }}
                >
                  <CartesianGrid
                    strokeDasharray="3 3"
                    stroke="var(--border)"
                    vertical={false}
                  />
                  <XAxis
                    dataKey="game"
                    tick={{ fill: "var(--text-muted)", fontSize: 12 }}
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(v) => `$${v}`}
                    width={65}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="profit" radius={[4, 4, 0, 0]}>
                    {gameChartData.map((entry, i) => (
                      <Cell
                        key={i}
                        fill={GAME_COLORS[entry.game] || "#4ab3d8"}
                        fillOpacity={entry.profit >= 0 ? 1 : 0.5}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Per-game detail cards */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
              gap: 16,
              marginBottom: 8,
            }}
          >
            {activeGames.map((game) => (
              <GameCard key={game} game={game} data={gameStats[game]} />
            ))}
          </div>
        </>
      )}

      {/* Binder Performance */}
      {(binderCost > 0 || binderRevenue > 0) && (
        <>
          <SectionTitle>📒 Binder Performance</SectionTitle>
          <div className="card" style={{ marginBottom: 16 }}>
            <StatRow
              label="Binder Revenue"
              value={fmt(binderRevenue)}
              color="var(--green)"
              sub={`${binderOther.length} sale${binderOther.length !== 1 ? "s" : ""} from binder`}
            />
            <StatRow
              label="Binder Stocking Cost"
              value={`-${fmt(binderCost)}`}
              color="var(--danger)"
              sub={`${binderExpenses.length} restock${binderExpenses.length !== 1 ? "s" : ""}`}
            />
            <StatRow
              label="Binder Net Profit"
              value={fmtSigned(binderProfit)}
              color={binderProfit >= 0 ? "var(--green)" : "var(--danger)"}
            />
            {binderCost > 0 && (
              <StatRow
                label="Return on Binder Investment"
                value={`${((binderRevenue / binderCost) * 100).toFixed(0)}%`}
                color={
                  binderRevenue >= binderCost ? "var(--green)" : "var(--danger)"
                }
                sub="Revenue as % of stocking cost"
              />
            )}
            <MatchedEntries
              binderExpenses={binderExpenses}
              binderOther={binderOther}
            />
          </div>
          {binderMonthlyData.length > 1 && (
            <div className="card" style={{ marginBottom: 8 }}>
              <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 12 }}>
                Binder Profit by Month
              </div>
              <ResponsiveContainer width="100%" height={200}>
                <BarChart
                  data={binderMonthlyData}
                  margin={{ top: 5, right: 10, left: 10, bottom: 0 }}
                >
                  <CartesianGrid
                    strokeDasharray="3 3"
                    stroke="var(--border)"
                    vertical={false}
                  />
                  <XAxis
                    dataKey="month"
                    tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(v) => `$${v}`}
                    width={55}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="profit" radius={[4, 4, 0, 0]}>
                    {binderMonthlyData.map((entry, i) => (
                      <Cell
                        key={i}
                        fill={entry.profit >= 0 ? "#4caf7d" : "#e05c5c"}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </>
      )}

      {/* What This Means */}
      {insights.length > 0 && (
        <>
          <SectionTitle>What This Means</SectionTitle>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {insights.map((ins, i) => (
              <InsightBox key={i} {...ins} />
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default Insights;
