import React, { useEffect, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ReferenceLine,
  ResponsiveContainer,
} from "recharts";
import { API_BASE } from "../config";

const MIN_DATE = new Date("2020-01-01");

const isValidDate = (d) => {
  const date = new Date(d);
  return d && !isNaN(date.getTime()) && date >= MIN_DATE;
};

const SkeletonCard = () => (
  <div className="stat-card">
    <div
      className="skeleton"
      style={{ height: 11, width: "55%", marginBottom: 10 }}
    />
    <div className="skeleton" style={{ height: 30, width: "75%" }} />
  </div>
);

const StatCard = ({ label, value, color, accent }) => (
  <div className={`stat-card ${accent ? "stat-card--accent" : ""}`}>
    <div className="stat-card__label">{label}</div>
    <div className="stat-card__value" style={{ color: color || "var(--text)" }}>
      {value}
    </div>
  </div>
);

const FunFactCard = ({ emoji, label, value, sub, color }) => (
  <div
    className="card"
    style={{ display: "flex", flexDirection: "column", gap: 6 }}
  >
    <div style={{ fontSize: 24 }}>{emoji}</div>
    <div
      style={{
        fontSize: 11,
        fontWeight: 700,
        textTransform: "uppercase",
        letterSpacing: "0.8px",
        color: "var(--text-muted)",
      }}
    >
      {label}
    </div>
    <div
      style={{
        fontFamily: "'Bebas Neue', sans-serif",
        fontSize: 22,
        letterSpacing: 1,
        color: color || "var(--text)",
        lineHeight: 1.2,
      }}
    >
      {value}
    </div>
    {sub && (
      <div
        style={{
          fontSize: 12,
          color: "var(--text-muted)",
          fontStyle: "italic",
        }}
      >
        {sub}
      </div>
    )}
  </div>
);

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    const val = payload[0].value;
    return (
      <div
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
          borderRadius: "var(--radius-sm)",
          padding: "10px 14px",
          fontSize: 13,
        }}
      >
        <div style={{ color: "var(--text-muted)", marginBottom: 4 }}>
          {label}
        </div>
        <div
          style={{
            fontWeight: 700,
            color: val >= 0 ? "var(--green)" : "var(--danger)",
          }}
        >
          {val >= 0 ? "+" : ""}${val.toFixed(2)}
        </div>
      </div>
    );
  }
  return null;
};

const daysBetween = (a, b) =>
  Math.round(Math.abs(new Date(b) - new Date(a)) / (1000 * 60 * 60 * 24));

const buildChartData = (itemsData, expensesData, otherData, excludeUnsold) => {
  const events = [];

  itemsData.forEach((item) => {
    const isSold = item.soldPrice != null;

    // Only include purchase cost if: item is sold, OR we're not excluding unsold
    if (!excludeUnsold || isSold) {
      if (isValidDate(item.purchaseDate)) {
        events.push({
          date: new Date(item.purchaseDate),
          delta: -Number(item.purchasePrice),
        });
      }
    }

    // Sale always included
    if (isSold && isValidDate(item.soldDate)) {
      events.push({
        date: new Date(item.soldDate),
        delta: Number(item.soldPrice),
      });
    }
  });

  expensesData.forEach((exp) => {
    if (isValidDate(exp.date)) {
      events.push({ date: new Date(exp.date), delta: -Number(exp.amount) });
    }
  });

  otherData.forEach((o) => {
    if (isValidDate(o.date)) {
      events.push({ date: new Date(o.date), delta: Number(o.amount) });
    }
  });

  events.sort((a, b) => a.date - b.date);

  const byDate = {};
  events.forEach(({ date, delta }) => {
    const key = date.toISOString().split("T")[0];
    byDate[key] = (byDate[key] || 0) + delta;
  });

  let cumulative = 0;
  return Object.entries(byDate)
    .sort(([a], [b]) => new Date(a) - new Date(b))
    .map(([date, delta]) => {
      cumulative += delta;
      return { date, profit: parseFloat(cumulative.toFixed(2)) };
    });
};

const Home = () => {
  const [stats, setStats] = useState(null);
  const [facts, setFacts] = useState(null);
  const [itemsData, setItemsData] = useState([]);
  const [expensesData, setExpensesData] = useState([]);
  const [otherData, setOtherData] = useState([]);
  const [excludeUnsold, setExcludeUnsold] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [itemsRes, expensesRes, otherRes] = await Promise.all([
          fetch(`${API_BASE}/api/items`),
          fetch(`${API_BASE}/api/expenses`),
          fetch(`${API_BASE}/api/other`),
        ]);
        const [items, expenses, other] = await Promise.all([
          itemsRes.json(),
          expensesRes.json(),
          otherRes.json(),
        ]);

        setItemsData(items);
        setExpensesData(expenses);
        setOtherData(other);

        // ── Stats ──
        let totalPurchaseValue = 0,
          totalSoldValue = 0;
        let soldItems = 0,
          unsoldItems = 0,
          inventoryValue = 0;

        items.forEach((item) => {
          totalPurchaseValue += Number(item.purchasePrice);
          if (item.soldPrice != null) {
            soldItems++;
            totalSoldValue += Number(item.soldPrice);
          } else {
            unsoldItems++;
            inventoryValue += Number(item.purchasePrice);
          }
        });

        const totalExpenses = expenses.reduce(
          (s, e) => s + Number(e.amount),
          0,
        );
        const otherProfit = other.reduce((s, o) => s + Number(o.amount), 0);
        const totalMoneyIn = totalSoldValue + otherProfit;
        const totalMoneyOut = totalPurchaseValue + totalExpenses;
        const netProfit = totalMoneyIn - totalMoneyOut;

        setStats({
          netProfit,
          totalItems: items.length,
          soldItems,
          unsoldItems,
          inventoryValue,
          totalExpenses,
          otherProfit,
          totalMoneyIn,
          totalMoneyOut,
        });

        // ── Fun Facts ──
        const soldItemsList = items.filter((i) => i.soldPrice != null);

        const biggestSale = soldItemsList.reduce(
          (best, i) =>
            Number(i.soldPrice) > Number(best?.soldPrice || 0) ? i : best,
          null,
        );

        const biggestWin = soldItemsList.reduce((best, i) => {
          const profit = Number(i.soldPrice) - Number(i.purchasePrice);
          const bestProfit = best
            ? Number(best.soldPrice) - Number(best.purchasePrice)
            : -Infinity;
          return profit > bestProfit ? i : best;
        }, null);

        const biggestLoss = soldItemsList.reduce((worst, i) => {
          const profit = Number(i.soldPrice) - Number(i.purchasePrice);
          const worstProfit = worst
            ? Number(worst.soldPrice) - Number(worst.purchasePrice)
            : Infinity;
          return profit < worstProfit ? i : worst;
        }, null);

        const withHoldTime = soldItemsList
          .filter((i) => isValidDate(i.purchaseDate) && isValidDate(i.soldDate))
          .map((i) => ({
            ...i,
            holdDays: daysBetween(i.purchaseDate, i.soldDate),
          }));

        const longestHold = withHoldTime.reduce(
          (best, i) => (i.holdDays > (best?.holdDays || 0) ? i : best),
          null,
        );

        const fastestFlip = withHoldTime.reduce(
          (best, i) => (i.holdDays < (best?.holdDays ?? Infinity) ? i : best),
          null,
        );

        const wins = soldItemsList.filter(
          (i) => Number(i.soldPrice) > Number(i.purchasePrice),
        ).length;
        const winRate =
          soldItemsList.length > 0
            ? ((wins / soldItemsList.length) * 100).toFixed(0)
            : 0;

        const totalCardProfit = soldItemsList.reduce(
          (s, i) => s + (Number(i.soldPrice) - Number(i.purchasePrice)),
          0,
        );
        const avgProfit =
          soldItemsList.length > 0
            ? (totalCardProfit / soldItemsList.length).toFixed(2)
            : 0;

        const avgHold =
          withHoldTime.length > 0
            ? Math.round(
                withHoldTime.reduce((s, i) => s + i.holdDays, 0) /
                  withHoldTime.length,
              )
            : 0;

        const mostExpensiveUnsold = items
          .filter((i) => i.soldPrice == null)
          .reduce(
            (best, i) =>
              Number(i.purchasePrice) > Number(best?.purchasePrice || 0)
                ? i
                : best,
            null,
          );

        const byMonth = {};
        soldItemsList.forEach((i) => {
          if (!isValidDate(i.soldDate)) return;
          const key = new Date(i.soldDate).toISOString().slice(0, 7);
          byMonth[key] =
            (byMonth[key] || 0) +
            (Number(i.soldPrice) - Number(i.purchasePrice));
        });
        const bestMonthKey = Object.entries(byMonth).sort(
          (a, b) => b[1] - a[1],
        )[0];
        const bestMonth = bestMonthKey
          ? { month: bestMonthKey[0], profit: bestMonthKey[1].toFixed(2) }
          : null;

        setFacts({
          biggestSale,
          biggestWin,
          biggestLoss,
          longestHold,
          fastestFlip,
          winRate,
          avgProfit,
          avgHold,
          mostExpensiveUnsold,
          bestMonth,
          totalSold: soldItemsList.length,
        });
      } catch (err) {
        console.error(err);
        setError(true);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const chartData = buildChartData(
    itemsData,
    expensesData,
    otherData,
    excludeUnsold,
  );

  const fmt = (n) => `$${Math.abs(Number(n)).toFixed(2)}`;
  const sign = (n) => (Number(n) >= 0 ? "+" : "-");
  const fmtMonth = (m) => {
    if (!m) return "—";
    const [year, month] = m.split("-");
    return new Date(year, month - 1).toLocaleString("default", {
      month: "long",
      year: "numeric",
    });
  };

  // Realized P&L (sold cards only) for toggle label
  const realizedPnL =
    itemsData
      .filter((i) => i.soldPrice != null)
      .reduce((s, i) => s + Number(i.soldPrice) - Number(i.purchasePrice), 0) +
    otherData.reduce((s, o) => s + Number(o.amount), 0) -
    expensesData.reduce((s, e) => s + Number(e.amount), 0);

  return (
    <div>
      <h1 className="page-title">Dashboard</h1>

      {loading || !stats ? (
        <div className="stats-grid">
          {error && !loading ? (
            <div
              style={{
                gridColumn: "1 / -1",
                color: "var(--danger)",
                padding: 20,
              }}
            >
              ⚠️ Could not load data. Check your connection or try refreshing.
            </div>
          ) : (
            Array(9)
              .fill(0)
              .map((_, i) => <SkeletonCard key={i} />)
          )}
        </div>
      ) : (
        <>
          <div className="stats-grid" style={{ marginBottom: 16 }}>
            <div
              className="stat-card stat-card--accent"
              style={{ gridColumn: "span 2" }}
            >
              <div className="stat-card__label">Net Profit</div>
              <div
                className="stat-card__value"
                style={{
                  fontSize: 48,
                  color:
                    stats.netProfit >= 0 ? "var(--green)" : "var(--danger)",
                }}
              >
                {sign(stats.netProfit)}
                {fmt(stats.netProfit)}
              </div>
            </div>
            <StatCard
              label="Total Money In"
              value={`+${fmt(stats.totalMoneyIn)}`}
              color="var(--green)"
            />
            <StatCard
              label="Total Money Out"
              value={`-${fmt(stats.totalMoneyOut)}`}
              color="var(--danger)"
            />
            <StatCard
              label="Total Expenses"
              value={`-${fmt(stats.totalExpenses)}`}
              color="var(--danger)"
            />
            <StatCard
              label="Other Profits"
              value={`+${fmt(stats.otherProfit)}`}
              color="var(--green)"
            />
          </div>

          <div className="stats-grid" style={{ marginBottom: 32 }}>
            <StatCard label="Total Items" value={stats.totalItems} />
            <StatCard
              label="Sold Items"
              value={stats.soldItems}
              color="var(--green)"
            />
            <StatCard
              label="Unsold Items"
              value={stats.unsoldItems}
              color="var(--accent)"
            />
            <StatCard
              label="Inventory Value"
              value={fmt(stats.inventoryValue)}
            />
          </div>

          {/* Chart */}
          {chartData.length > 1 && (
            <div className="card" style={{ marginBottom: 32 }}>
              <div
                style={{
                  marginBottom: 16,
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  flexWrap: "wrap",
                  gap: 12,
                }}
              >
                <div>
                  <div
                    style={{
                      fontFamily: "'Bebas Neue', sans-serif",
                      fontSize: 20,
                      letterSpacing: 1,
                    }}
                  >
                    Cumulative Profit Over Time
                  </div>
                  <div
                    style={{
                      fontSize: 12,
                      color: "var(--text-muted)",
                      marginTop: 2,
                    }}
                  >
                    {excludeUnsold
                      ? "Showing realized P&L only — unsold card costs excluded"
                      : "All cash events — purchases, sales, expenses, other profits"}
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                  <div
                    style={{
                      fontFamily: "'Bebas Neue', sans-serif",
                      fontSize: 22,
                      color: excludeUnsold
                        ? realizedPnL >= 0
                          ? "var(--green)"
                          : "var(--danger)"
                        : stats.netProfit >= 0
                          ? "var(--green)"
                          : "var(--danger)",
                    }}
                  >
                    {excludeUnsold
                      ? `${sign(realizedPnL)}${fmt(realizedPnL)}`
                      : `${sign(stats.netProfit)}${fmt(stats.netProfit)}`}
                  </div>
                  <button
                    className={`btn btn-sm ${excludeUnsold ? "btn-primary" : "btn-secondary"}`}
                    onClick={() => setExcludeUnsold((p) => !p)}
                  >
                    {excludeUnsold ? "Realized Only" : "All Trades"}
                  </button>
                </div>
              </div>

              <ResponsiveContainer width="100%" height={300}>
                <LineChart
                  data={chartData}
                  margin={{ top: 10, right: 10, left: 10, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
                  <XAxis
                    dataKey="date"
                    tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                    tickLine={false}
                    axisLine={{ stroke: "var(--border)" }}
                    tickFormatter={(val) => {
                      const d = new Date(val + "T00:00:00");
                      return `${d.toLocaleString("default", { month: "short" })} ${d.getFullYear()}`;
                    }}
                    interval="preserveStartEnd"
                  />
                  <YAxis
                    tick={{ fill: "var(--text-muted)", fontSize: 11 }}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(val) => `$${val}`}
                    width={75}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <ReferenceLine
                    y={0}
                    stroke="var(--border-light)"
                    strokeDasharray="4 4"
                  />
                  <Line
                    type="monotone"
                    dataKey="profit"
                    stroke="#4ab3d8"
                    strokeWidth={2}
                    dot={false}
                    activeDot={{
                      r: 5,
                      fill: "#4ab3d8",
                      stroke: "var(--bg-card)",
                      strokeWidth: 2,
                    }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Fun Facts */}
          {facts && (
            <>
              <h2
                style={{
                  fontFamily: "'Bebas Neue', sans-serif",
                  fontSize: 24,
                  letterSpacing: 2,
                  marginBottom: 16,
                  color: "var(--text-muted)",
                }}
              >
                Fun Facts
              </h2>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))",
                  gap: 16,
                  marginBottom: 32,
                }}
              >
                <FunFactCard
                  emoji="🏆"
                  label="Biggest Win"
                  value={
                    facts.biggestWin
                      ? `+${fmt(Number(facts.biggestWin.soldPrice) - Number(facts.biggestWin.purchasePrice))}`
                      : "—"
                  }
                  sub={facts.biggestWin?.name}
                  color="var(--green)"
                />

                <FunFactCard
                  emoji="💸"
                  label="Biggest Loss"
                  value={
                    facts.biggestLoss
                      ? `-${fmt(Math.abs(Number(facts.biggestLoss.soldPrice) - Number(facts.biggestLoss.purchasePrice)))}`
                      : "—"
                  }
                  sub={facts.biggestLoss?.name}
                  color="var(--danger)"
                />

                <FunFactCard
                  emoji="💰"
                  label="Biggest Sale"
                  value={
                    facts.biggestSale ? fmt(facts.biggestSale.soldPrice) : "—"
                  }
                  sub={facts.biggestSale?.name}
                  color="var(--accent)"
                />

                <FunFactCard
                  emoji="⏳"
                  label="Longest Hold"
                  value={
                    facts.longestHold
                      ? `${facts.longestHold.holdDays} days`
                      : "—"
                  }
                  sub={facts.longestHold?.name}
                  color="var(--blue)"
                />

                <FunFactCard
                  emoji="⚡"
                  label="Fastest Flip"
                  value={
                    facts.fastestFlip
                      ? facts.fastestFlip.holdDays === 0
                        ? "Same day"
                        : `${facts.fastestFlip.holdDays} day${facts.fastestFlip.holdDays !== 1 ? "s" : ""}`
                      : "—"
                  }
                  sub={facts.fastestFlip?.name}
                  color="var(--green)"
                />

                <FunFactCard
                  emoji="🎯"
                  label="Win Rate"
                  value={`${facts.winRate}%`}
                  sub={`${facts.totalSold} cards sold`}
                  color={
                    Number(facts.winRate) >= 50
                      ? "var(--green)"
                      : "var(--danger)"
                  }
                />

                <FunFactCard
                  emoji="📊"
                  label="Avg Profit / Card"
                  value={`${Number(facts.avgProfit) >= 0 ? "+" : ""}${fmt(facts.avgProfit)}`}
                  sub="Per sold item"
                  color={
                    Number(facts.avgProfit) >= 0
                      ? "var(--green)"
                      : "var(--danger)"
                  }
                />

                <FunFactCard
                  emoji="📅"
                  label="Avg Hold Time"
                  value={facts.avgHold > 0 ? `${facts.avgHold} days` : "—"}
                  sub="From buy to sell"
                  color="var(--text)"
                />

                {facts.bestMonth && (
                  <FunFactCard
                    emoji="🔥"
                    label="Best Month"
                    value={`+${fmt(facts.bestMonth.profit)}`}
                    sub={fmtMonth(facts.bestMonth.month)}
                    color="var(--green)"
                  />
                )}

                {facts.mostExpensiveUnsold && (
                  <FunFactCard
                    emoji="💎"
                    label="Most Expensive Unsold"
                    value={fmt(facts.mostExpensiveUnsold.purchasePrice)}
                    sub={facts.mostExpensiveUnsold.name}
                    color="var(--accent)"
                  />
                )}
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
};

export default Home;
